// Cloudflare Worker & Pages Entry Point
// Supports both Cloudflare Workers and Cloudflare Pages deployments

const jsonHeaders = {
  "Content-Type": "application/json; charset=utf-8",
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET, POST, DELETE, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type"
};

const INIT_SQL = `
CREATE TABLE IF NOT EXISTS tasks (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  options TEXT NOT NULL DEFAULT \x27[]\x27,
  note TEXT DEFAULT \x27\x27,
  description TEXT DEFAULT \x27\x27,
  date TEXT NOT NULL,
  deadline TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT \x27todo\x27,
  assignee_ids TEXT NOT NULL DEFAULT \x27["non"]\x27,
  priority TEXT NOT NULL DEFAULT \x27normal\x27,
  color TEXT NOT NULL DEFAULT \x27blue\x27,
  created_at TEXT DEFAULT (datetime(\x27now\x27)),
  updated_at TEXT DEFAULT (datetime(\x27now\x27))
);
CREATE INDEX IF NOT EXISTS idx_tasks_deadline ON tasks(deadline);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks(status);
CREATE INDEX IF NOT EXISTS idx_tasks_date ON tasks(date);
CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
`;

function getDb(env) {
  if (!env) return null;
  if (env.DB && typeof env.DB.prepare === 'function') return env.DB;
  if (env.db && typeof env.db.prepare === 'function') return env.db;
  if (env['team-taskflow-db'] && typeof env['team-taskflow-db'].prepare === 'function') return env['team-taskflow-db'];
  if (env.team_taskflow_db && typeof env.team_taskflow_db.prepare === 'function') return env.team_taskflow_db;
  if (env.DATABASE && typeof env.DATABASE.prepare === 'function') return env.DATABASE;
  if (env.D1 && typeof env.D1.prepare === 'function') return env.D1;
  for (const key of Object.keys(env)) {
    try {
      if (env[key] && typeof env[key].prepare === 'function') {
        return env[key];
      }
    } catch (e) {}
  }
  return null;
}

async function ensureTable(db) {
  if (!db) return;
  try {
    const stmts = INIT_SQL.trim().split(";").map(s => s.trim()).filter(Boolean);
    for (const sql of stmts) {
      await db.prepare(sql).run();
    }
  } catch (err) {
    console.error("Error ensuring table:", err);
  }
}


